CREATE TABLE integrations_maintenance (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging')), PRIMARY KEY(workspace_id,project_id));
ALTER TABLE integrations_links ADD COLUMN project_id TEXT;
ALTER TABLE integrations_deliveries ADD COLUMN project_id TEXT;
UPDATE integrations_deliveries SET project_id=(SELECT project_id FROM integrations_sources WHERE integrations_sources.workspace_id=integrations_deliveries.workspace_id AND integrations_sources.id=integrations_deliveries.source_id);
ALTER TABLE integrations_receipts ADD COLUMN project_id TEXT;
UPDATE integrations_receipts SET project_id=COALESCE((SELECT project_id FROM integrations_links WHERE workspace_id=integrations_receipts.workspace_id AND id=integrations_receipts.result_id),(SELECT project_id FROM integrations_sources WHERE workspace_id=integrations_receipts.workspace_id AND id=integrations_receipts.result_id),(SELECT project_id FROM integrations_deliveries WHERE workspace_id=integrations_receipts.workspace_id AND id=integrations_receipts.result_id),(SELECT project_id FROM integrations_feedback WHERE workspace_id=integrations_receipts.workspace_id AND issue_id=integrations_receipts.result_id));
ALTER TABLE integrations_history ADD COLUMN project_id TEXT;
ALTER TABLE integrations_events ADD COLUMN project_id TEXT;
UPDATE integrations_events SET project_id=COALESCE((SELECT project_id FROM integrations_links WHERE workspace_id=integrations_events.workspace_id AND id=integrations_events.aggregate_id),(SELECT project_id FROM integrations_sources WHERE workspace_id=integrations_events.workspace_id AND id=integrations_events.aggregate_id),(SELECT project_id FROM integrations_feedback WHERE workspace_id=integrations_events.workspace_id AND id=integrations_events.aggregate_id));
CREATE INDEX integrations_links_project ON integrations_links(workspace_id,project_id);
CREATE INDEX integrations_deliveries_project ON integrations_deliveries(workspace_id,project_id);
CREATE INDEX integrations_receipts_project ON integrations_receipts(workspace_id,project_id);
CREATE INDEX integrations_history_project ON integrations_history(workspace_id,project_id);
CREATE INDEX integrations_events_project ON integrations_events(workspace_id,project_id);
CREATE TRIGGER integrations_links_freeze_insert BEFORE INSERT ON integrations_links WHEN (EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id)) OR (EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=NEW.workspace_id AND project_id<>'' AND NEW.project_id IS NULL)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER integrations_links_freeze_update BEFORE UPDATE ON integrations_links WHEN ((EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id)) OR (EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=OLD.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=OLD.workspace_id AND project_id=OLD.project_id))) OR (EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=NEW.workspace_id AND project_id<>'' AND NEW.project_id IS NULL) OR EXISTS(SELECT 1 FROM integrations_maintenance WHERE workspace_id=OLD.workspace_id AND project_id<>'' AND OLD.project_id IS NULL)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
